async function api(path, options={}) {
 const response=await fetch('/api/v1'+path,{...options,headers:{'Content-Type':'application/json',...options.headers},credentials:'same-origin'});
 const body=await response.text();let data={};try{data=body?JSON.parse(body):{};}catch{throw new Error('The server returned an invalid response');}
 if(!response.ok){if(response.status===401 && path!='/auth/login') showLogin();const error=new Error(data.error || 'Request failed');error.status=response.status;error.code=data.code;error.field=data.field;error.how_to_fix=data.how_to_fix;throw error;}return data;
}
