async function startInventoryRefresh(scope,accountIDs){
 const run=++inventoryRefreshRun;inventoryRefreshState={scope,status:'queued'};updateInventoryRefreshStatus();
 try{
  let job=await send('/inventory/refresh?account_ids='+encodeURIComponent(accountIDs.join(',')),'POST',{});
  inventoryRefreshState={scope,...job};updateInventoryRefreshStatus();
  while(run===inventoryRefreshRun&&(job.status==='queued'||job.status==='running')){await sleep(900);job=await api('/inventory/refresh/'+encodeURIComponent(job.id));inventoryRefreshState={scope,...job};updateInventoryRefreshStatus();}
  if(run!==inventoryRefreshRun)return;
  if(job.status==='partial')toast(`${job.failed_accounts.length} account refresh failed; showing its last successful snapshot.`);
  if(job.status==='failed')toast('Live refresh failed; the latest healthy snapshot is still visible. '+(job.error||''));
  if(page==='instances'&&inventoryScope()===scope)await render();
 }catch(error){if(run!==inventoryRefreshRun)return;inventoryRefreshState={scope,status:'failed',error:error.message};updateInventoryRefreshStatus();toast('Live refresh failed; the latest healthy snapshot is still visible. '+error.message);}
}
