const iconButton=(icon,label,action,kind,id,region='')=>`<button type="button" class="${kind} table-icon-button" data-action="${action}" data-id="${esc(id)}"${region?` data-region="${esc(region)}"`:''} aria-label="${esc(label)}" title="${esc(label)}">${actionIcons[icon]}</button>`;
